// Same-origin dashboard. Research and simulation belong to the Python worker.
import {sampleData} from './engine.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const quoteMoney=(x,q='USD')=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2,minimumFractionDigits:2}).format(x)+' '+esc(q);
const money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(x), pct=x=>(100*x).toFixed(2)+'%';
let historicalCatalog=[],health={},workspace={datasets:[],runs:[],jobs:[],papers:[]},paperDetail=null,selected=sessionStorage.getItem('tradoor.dataset')||'',pollBusy=false;
let noticeText='';
async function api(path,body){const r=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});let value;try{value=await r.json();}catch{throw Error('Python API not reachable. Start the Tradoor API; the static preview cannot run backend jobs.');}if(!r.ok){const detail=value.detail;const e=Error(typeof detail==='string'?detail:JSON.stringify(detail));e.status=r.status;throw e;}return value;}
function toast(s){noticeText=s;$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function download(name,value){const u=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function page(){return location.hash.slice(1)||'overview';}
const names={overview:'Overview',research:'Factor research',backtests:'Backtesting',paper:'Paper trading',live:'Live trading',data:'Data library',settings:'Settings & readiness'};
function title(k,n,d){return `<div class="page-title"><div><div class="eyebrow">${k}</div><h1>${n}</h1><p>${d}</p></div></div>`;}
function banner(){return `<div class="notice"><strong>${esc(health.engine||'Alphacore v12')}</strong><span>${health.engine_ready?'Engine connected':'Engine not connected'} · Python API · ${health.worker?.online?'worker online':'worker offline'}</span><a href="#settings">Connection details ↗</a></div>`;}
function card(name,body,badge=''){return `<section class="card wide"><div class="card-head"><h2>${name}</h2>${badge?`<span class="badge neutral">${badge}</span>`:''}</div><div class="card-body">${body}</div></section>`;}
function button(label,id,disabled=false,primary=false){return `<button id="${id}" ${disabled?'disabled':''} class="${primary?'primary':''}">${label}</button>`;}
function chart(curve,quote){if(!curve?.length)return '<div class="empty">No server equity observations yet.</div>';const vals=curve.map(p=>p.equity),lo=Math.min(...vals),hi=Math.max(...vals),range=Math.max(hi-lo,1),points=vals.map((v,i)=>`${i/Math.max(1,vals.length-1)*800},${215-(v-lo)/range*190}`).join(' ');return `<svg class="chart" viewBox="0 0 800 240" preserveAspectRatio="none" role="img" aria-label="Server equity curve">${[25,72,120,168,215].map(y=>`<line class="chart-grid" x1="0" y1="${y}" x2="800" y2="${y}"/>`).join('')}<polyline class="chart-line" points="${points}"/></svg><div class="chart-labels"><span>${esc(curve[0].date)}</span><span>${quote?quoteMoney(lo,quote):money(lo)} – ${quote?quoteMoney(hi,quote):money(hi)}</span><span>${esc(curve.at(-1).date)}</span></div>`;}
function stats(run){const m=run?.metrics||{};return `<div class="stats">${[['Equity',run?money(run.equity):'—'],['Total return',m.totalReturn==null?'—':pct(m.totalReturn)],['Sharpe',m.sharpe==null?'—':m.sharpe.toFixed(2)],['Max drawdown',m.maxDrawdown==null?'—':pct(m.maxDrawdown)]].map(([k,v])=>`<div class="stat"><div class="stat-label">${k}</div><div class="stat-value">${v}</div><div class="stat-note">${run?'Server result':'Awaiting engine evidence'}</div></div>`).join('')}</div>`;}
function jobs(){return workspace.jobs.length?`<table><thead><tr><th>JOB</th><th>STATUS</th><th>DETAILS</th></tr></thead><tbody>${workspace.jobs.map(j=>`<tr><td>${esc(j.config.name)}<small>${esc(j.id.slice(0,12))}</small></td><td>${esc(j.status)}</td><td>${esc(j.error||j.result_id||'Waiting for worker')}</td></tr>`).join('')}</tbody></table>`:'<p>No server jobs submitted.</p>';}
function overview(){const run=workspace.runs[0];return title('PYTHON RESEARCH WORKSPACE','From research to forward testing.','The dashboard reads persistent server results. No browser backtest engine is used.')+banner()+stats(run)+card('Portfolio performance',chart(run?.curve)+`<p>${esc(run?.attribution)}</p>`,run?'SERVER BACKTEST':'AWAITING FIRST RUN')+card('Research jobs',jobs())+card('Simulation service',`<p>${workspace.papers.length} paper runs stored. ${workspace.papers.filter(p=>p.status==='running').length} active. Simulated fills use public prices and never submit exchange orders.</p><div class="actions"><a href="#paper">Open paper trading ↗</a><a href="#data">Import price data ↗</a></div>`);}
function datasetOptions(){return workspace.datasets.map(d=>`<option value="${d.id}" ${selected===d.id?'selected':''}>${esc(d.source)} · ${d.symbols.length} assets · ${d.bars} days</option>`).join('');}
function backtests(){return title('BACKEND STRATEGY LAB','Run research in Alphacore v12.','The API queues a job; the Python worker saves the result independently of this browser.')+banner()+card('New backend backtest',`<form id="backend-form"><div class="form-grid"><label>Dataset<select name="dataset_id">${datasetOptions()||'<option value="">Import data first</option>'}</select></label><label>Strategy name<input name="name" required maxlength="80" value="Momentum baseline"></label><label>Signal<select name="mode"><option value="momentum">V12 scaled momentum</option><option value="reversal">V12 scaled reversal</option></select></label><label>Starting capital (quote units)<input name="capital" type="number" value="100000" min="100" max="1000000000" required></label><label>Lookback (daily bars)<input name="lookback" type="number" value="20" min="1" max="200" required></label><label>Assets per side<input name="selection" type="number" value="1" min="1" max="10" required></label><label>Fee (bps)<input name="feeBps" type="number" value="5" step=".1" min="0" max="500" required></label><label>Slippage (bps)<input name="slippageBps" type="number" value="2" step=".1" min="0" max="500" required></label></div><div class="actions"><button class="primary" type="submit" ${!health.engine_ready||!workspace.datasets.length?'disabled':''}>Queue backend backtest →</button><span class="muted">${health.engine_ready?'Results remain on the server after closing this page.':'Waiting for the private Alphacore v12 adapter.'}</span></div><p id="form-error" class="error" role="alert"></p></form>`)+card('Job queue',`<div id="jobs-table" class="table-scroll">${jobs()}</div>`)+workspace.runs.map(r=>card(esc(r.name),stats(r)+chart(r.curve)+`<p>${esc(r.attribution)}</p><p>${esc(r.assumptions||'')}</p><div class="actions"><button data-export="${r.id}">Export server result</button><a href="#paper">Forward-test configuration ↗</a></div>`,'SERVER RESULT')).join('');}
function dataPage(){return title('SERVER DATA LIBRARY','Persist the evidence.','Datasets are stored in SQLite with immutable identifiers and SHA-256 hashes.')+banner()+card('Historical data available to this workspace',historicalCatalog.map(d=>`<div class="step"><div><h3>${esc(d.label)}</h3><p>${esc(d.description)}</p><p>${esc(d.attribution)}</p><button data-catalog="${esc(d.id)}">Import historical dataset</button></div></div>`).join('')||'<p>No historical datasets are currently granted to this workspace.</p>')+card('Import public exchange history',`<form id="market-form"><div class="form-grid"><label>Venue<select name="exchange"><option value="binance">Binance</option><option value="kraken">Kraken</option></select></label><label>Exchange symbols<input name="symbols" value="BTC/USDT,ETH/USDT" required></label><label>Closed daily bars<input name="bars" type="number" value="600" min="500" max="800" required></label></div><div class="actions"><button class="primary">Import public history</button><span class="muted">No account keys needed · closed daily candles only</span></div><p id="market-error" class="error" role="alert"></p></form>`)+card('Import daily prices',`<p>CSV format: date,symbol,close. Use consecutive daily prices for 2–20 assets and at least five dates. V12 backtests require at least 500 dates; uploads accept up to 100,000 rows.</p><div class="code mono">date,symbol,close\n2025-01-01,BTC/USDT,94500\n2025-01-01,ETH/USDT,3350</div><div class="actions"><label>CSV file<input id="csv-file" type="file" accept=".csv,text/csv"></label>${button('Import to server','import-data',false,true)}${button('Load synthetic sample','sample-data')}</div><p id="data-error" class="error" role="alert"></p>`)+card('Saved datasets',workspace.datasets.map(d=>`<div class="step"><div><h3>${esc(d.source)}</h3><p>${d.symbols.map(esc).join(' · ')} · ${d.bars} dates</p><p>${esc(d.attribution)}</p><small class="mono">${esc(d.id)} · SHA-256 ${esc(d.sha256)}</small><button class="button-small" data-select="${d.id}">Use in backtest</button></div></div>`).join('')||'<div class="empty">No server datasets yet.</div>');}
function paper(){const p=paperDetail;const latestDataset=workspace.datasets.find(d=>d.id===workspace.runs[0]?.dataset_id);const defaultSymbols=latestDataset?.symbols.map(s=>s.includes('/')?s:s+'/USDT').join(',')||'BTC/USDT,ETH/USDT';return title('CONTINUOUS SIMULATION','Forward-test with a server worker.','The worker polls public prices and marks paper positions every 15 seconds. Closed daily bars trigger rebalances.')+banner()+card('Start a simulated run',`<form id="paper-form"><div class="form-grid"><label>Completed backend backtest<select name="backtest_id">${workspace.runs.map(r=>`<option value="${r.id}">${esc(r.name)}</option>`).join('')||'<option value="">No completed backend run</option>'}</select></label><label>Public price venue<select name="exchange"><option value="binance">Binance</option><option value="kraken">Kraken</option></select></label><label>Exchange symbols (comma separated)<input name="symbols" value="${esc(defaultSymbols)}" required></label><label>Drawdown halt (%)<input name="drawdown" type="number" value="20" min="1" max="50" required></label></div><p>Use the same assets as the source backtest. Short legs are synthetic: funding, borrow, margin and liquidation are not modeled. This is not a testnet order service.</p><label style="margin-top:15px"><input style="display:inline;width:auto;margin-right:8px" type="checkbox" name="ack" required>I understand this starts an ongoing simulated run using public market data.</label><div class="actions"><button class="primary" ${!health.engine_ready||!workspace.runs.length?'disabled':''}>Start continuous paper run</button></div><p id="paper-error" class="error" role="alert"></p></form>`)+card('Paper runs',`<div class="table-scroll"><table><thead><tr><th>RUN</th><th>STATUS</th><th>EQUITY</th><th>DATA</th><th></th></tr></thead><tbody>${workspace.papers.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.exchange)} · ${esc(p.frequency)}</small></td><td>${esc(p.status)}</td><td>${quoteMoney(p.equity,p.quote_currency)}</td><td>${esc(p.data_status)}<small>${esc(p.error)}</small></td><td><button data-paper="${p.id}">Inspect</button></td></tr>`).join('')||'<tr><td colspan="5">No server paper runs.</td></tr>'}</tbody></table></div>`)+(p?paperView(p):'');}
function paperView(p){return card(esc(p.name),`<div class="balance-row"><span>${esc(p.status)} · ${esc(p.data_status)}</span><strong>${quoteMoney(p.equity,p.quote_currency)}</strong></div><p>Cash: ${quoteMoney(p.cash,p.quote_currency)} · Simulation PnL: ${quoteMoney(p.equity-p.capital,p.quote_currency)} · Last price check: ${p.observed_at?new Date(p.observed_at*1000).toLocaleString():'Awaiting first tick'}</p>${p.error?`<p class="error">${esc(p.error)}</p>`:''}${chart(p.curve,p.quote_currency)}<div class="actions">${['pause','resume','stop'].map(a=>`<button data-control="${a}" data-id="${p.id}" ${['stopped','halted'].includes(p.status)?'disabled':''}>${a[0].toUpperCase()+a.slice(1)}</button>`).join('')}<button id="export-paper">Export paper snapshot</button></div><p>Pause and stop freeze processing; they do not liquidate positions. Drawdown halts flatten simulated positions at the last validated marks.</p><h3 style="margin-top:24px">Positions</h3><div class="table-scroll"><table><thead><tr><th>SYMBOL</th><th>SIGNED QUANTITY</th><th>MARK</th></tr></thead><tbody>${Object.values(p.positions).map(x=>`<tr><td>${esc(x.symbol)}</td><td>${x.qty.toFixed(8)}</td><td>${quoteMoney(p.marks[x.symbol],p.quote_currency)}</td></tr>`).join('')||'<tr><td colspan="3">No positions yet.</td></tr>'}</tbody></table></div><h3 style="margin-top:24px">Recent fills (latest 200)</h3><div class="table-scroll"><table><thead><tr><th>TIME</th><th>ASSET</th><th>SIDE</th><th>QTY</th><th>PRICE</th><th>COST</th></tr></thead><tbody>${p.fills.map(f=>`<tr><td>${esc(f.date)}</td><td>${esc(f.symbol)}</td><td>${esc(f.side)}</td><td>${f.quantity.toFixed(8)}</td><td>${quoteMoney(f.price,p.quote_currency)}</td><td>${quoteMoney(f.cost,p.quote_currency)}</td></tr>`).join('')||'<tr><td colspan="6">No simulated fills.</td></tr>'}</tbody></table></div>`,'SIMULATED FUNDS');}
function settings(){return title('BACKEND CONNECTION','Inspect the running services.','Alphacore v12 is the selected target. There is no silent fallback to the browser or older engines.')+banner()+card('Service health',`<ul class="checks"><li>Python API<span class="done">Ready</span></li><li>Selected engine<span>${esc(health.engine)}</span></li><li>Engine adapter<span class="${health.engine_ready?'done':''}">${health.engine_ready?'Connected':'Not connected'}</span></li><li>Persistent worker<span class="${health.worker?.online?'done':''}">${health.worker?.online?'Online':'Offline'}</span></li><li>Storage<span class="done">SQLite server workspace</span></li><li>Access mode<span>${esc(health.mode)}</span></li><li>Real orders<span>Unavailable</span></li></ul>${health.engine_error?`<div class="callout">${esc(health.engine_error)}</div>`:''}<p>The private v12 adapter is installed server-side and selected through TRADOOR_ENGINE_FACTORY. It is never accepted from an API request. Local mode binds to loopback only; external deployment requires owner authentication and HTTPS.</p>`);}
function researchPage(){return title('PRIVATE RESEARCH LIBRARY','Factors and strategies.','Only evidence saved in this workspace appears here. Private production alpha is not imported automatically.')+banner()+card('Factor library','<p>No mined factor catalog has been imported. The connected demo adapter computes a scaled price-change factor for momentum/reversal tests; it is not a mined or approved alpha.</p>')+card('Saved strategy backtests',workspace.runs.map(r=>`<div class="step"><div><h3>${esc(r.name)}</h3><p>Completed backend research · ${esc(r.id)}</p><a href="#backtests">View backtest evidence ↗</a></div></div>`).join('')||'<p>No completed strategies in this workspace. Import prices in Data library, then run a backtest.</p>')+card('Private runner','<p>Customer-hosted research keeps code and input data on the customer machine. The offline runner writes a local report and does not upload alpha. Cloud report synchronization and mined-factor import are not connected yet.</p>');}
function render(){const p=page();$('#breadcrumb').textContent=names[p]||'Overview';document.querySelectorAll('[data-page]').forEach(a=>a.classList.toggle('active',a.dataset.page===p));const pages={overview,backtests,paper,data:dataPage,settings,research:researchPage,live:()=>title('LIVE EXECUTION','Exchange execution is not connected.','The new backend exposes simulation only. No exchange credentials or real-order routes exist.')+banner()+card('Execution status','<p>Continuous paper trading fetches public prices and creates a local simulated ledger. Live activation requires a separately verified execution adapter and explicit account/risk configuration.</p>')};$('#main').innerHTML=(pages[p]||overview)();bind();}
async function refresh(renderPage=true){health=await api('health');workspace=await api('workspace');historicalCatalog=(await api('catalog')).datasets;if(paperDetail)paperDetail=await api('paper/'+paperDetail.id);if(!selected&&workspace.datasets[0])selected=workspace.datasets[0].id;if(renderPage)render();}
function bind(){
 document.querySelectorAll('[data-catalog]').forEach(b=>b.onclick=async()=>{try{b.disabled=true;await api('catalog/'+encodeURIComponent(b.dataset.catalog)+'/import',{});toast('Historical dataset imported into your private workspace.');await refresh();}catch(e){toast(e.message);b.disabled=false;}});
 if($('#market-form'))$('#market-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;b.textContent='Fetching closed candles…';try{await api('datasets/market',{exchange:f.get('exchange'),symbols:String(f.get('symbols')).split(',').map(s=>s.trim()).filter(Boolean),bars:Number(f.get('bars'))});toast('Public daily history saved on the server.');await refresh();}catch(error){$('#market-error').textContent=error.message;b.disabled=false;b.textContent='Import public history';}};

 if($('#backend-form'))$('#backend-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),config={name:f.get('name'),mode:f.get('mode')};for(const k of ['capital','lookback','selection','feeBps','slippageBps'])config[k]=Number(f.get(k));try{await api('backtests',{dataset_id:f.get('dataset_id'),config});toast('Backend job queued. The worker will save its result.');await refresh();}catch(e){$('#form-error').textContent=e.message;}};
 async function upload(csv,source){await api('datasets',{csv,source});toast('Dataset saved on the Python server.');await refresh();}
 if($('#sample-data'))$('#sample-data').onclick=()=>upload(sampleData(600),'Synthetic sample · not market data').catch(e=>$('#data-error').textContent=e.message);
 if($('#import-data'))$('#import-data').onclick=async()=>{try{const f=$('#csv-file').files[0];if(!f)throw Error('Choose a CSV first');if(f.size>5e6)throw Error('CSV exceeds 5 MB');await upload(await f.text(),'Imported: '+f.name);}catch(e){$('#data-error').textContent=e.message;}};
 document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;sessionStorage.setItem('tradoor.dataset',selected);location.hash='backtests';});
 document.querySelectorAll('[data-export]').forEach(b=>b.onclick=async()=>{try{download('tradoor-backtest.json',await api('backtests/'+b.dataset.export));}catch(e){toast(e.message);}});
 if($('#paper-form'))$('#paper-form').onsubmit=async e=>{e.preventDefault();try{const f=new FormData(e.target),p=await api('paper',{backtest_id:f.get('backtest_id'),exchange:f.get('exchange'),symbols:String(f.get('symbols')).split(',').map(s=>s.trim()).filter(Boolean),frequency:'1d',drawdown_limit:Number(f.get('drawdown'))/100,acknowledge_simulation:f.get('ack')==='on'});paperDetail=await api('paper/'+p.id);toast('Continuous simulated run created.');await refresh();}catch(e){$('#paper-error').textContent=e.message;}};
 document.querySelectorAll('[data-paper]').forEach(b=>b.onclick=async()=>{try{paperDetail=await api('paper/'+b.dataset.paper);render();}catch(e){toast(e.message);}});
 document.querySelectorAll('[data-control]').forEach(b=>b.onclick=async()=>{try{await api('paper/'+b.dataset.id+'/'+b.dataset.control,{});await refresh();}catch(e){toast(e.message);}});
 if($('#export-paper'))$('#export-paper').onclick=()=>download('tradoor-paper.json',paperDetail);
}
function login(){ $('#main').innerHTML=title('OWNER WORKSPACE','Sign in to Tradoor.','Enter the owner token configured on this Python server. It is exchanged for an HttpOnly session cookie.')+card('Owner access','<form id="login-form"><label>Owner token<input name="token" type="password" autocomplete="current-password" required></label><div class="actions"><button class="primary">Sign in</button></div><p id="login-error" class="error" role="alert"></p></form>');$('#login-form').onsubmit=async e=>{e.preventDefault();try{await api('login',{token:new FormData(e.target).get('token')});await refresh();}catch(e){$('#login-error').textContent=e.message;}};}
async function start(){try{await refresh();}catch(e){if(e.status===401)login();else $('#main').innerHTML=title('BACKEND REQUIRED','Connect the Python workspace.','This dashboard requires its same-origin Python API.')+card('API unavailable',`<p>${esc(e.message)}</p><div class="code mono">python -m alphaloop.web.api --local\npython -m alphaloop.web.worker</div><p>Alphacore v12 must be connected server-side before research jobs or paper runs can start.</p>`);}}
window.addEventListener('hashchange',start);start();
setInterval(async()=>{if(pollBusy||document.hidden)return;pollBusy=true;try{await refresh(false);if(page()==='overview'||page()==='settings'||(page()==='paper'&&paperDetail&&!document.querySelector('#paper-form input:focus')))render();else if(page()==='backtests'&&$('#jobs-table'))$('#jobs-table').innerHTML=jobs();}catch(e){if(e.status===401)login();}finally{pollBusy=false;}},5000);
